update public.lessons l set enhancements = $ench${"industryStory":"A team consistently closed stories with a note reading \"automation to follow\" and a linked ticket. Those tickets piled up in a column everyone stopped reading, and within two quarters the automated suite covered barely half of what had shipped — every regression escaped through a gap the team had promised to fill and never did. When they changed their definition of done so a story could not be closed without its agreed automated coverage in the same pull request, the backlog of automation debt stopped growing almost overnight, because the coverage was now written while the feature was fresh in everyone’s mind rather than reconstructed months later.","visualAid":{"type":"flow","title":"A story with automation built in","steps":[{"label":"Refinement (three amigos)","detail":"Agree what \"correct\" means and what is hard to test; ask for testability hooks."},{"label":"Decide coverage by risk","detail":"Map each risk to a layer — unit, API or end-to-end — before coding."},{"label":"Build feature + tests together","detail":"Automation lands in the same pull request as the code it checks."},{"label":"Review together","detail":"Feature code and test code reviewed in one place, held to shared standards."},{"label":"Done = green agreed coverage","detail":"The story is not complete until its automation passes in the pipeline."}]},"davidTip":"In refinement, ask one deceptively simple question of every story: \"how would we reproduce the failure case on demand?\" If the honest answer is \"we could not easily\", you have found the testability gap while it is still a cheap conversation rather than an expensive retrofit."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 15 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"badGood":{"label":"a weak test vs the same test after review","bad":"~~~ts\n// Passes, \"covers\" checkout — and proves almost nothing.\ntest('test checkout', async ({ page }) => {\n  await page.goto('/checkout');\n  await page.getByLabel('Discount code').fill('SAVE10');\n  await page.locator('.css-1x2y3z').click();      // brittle generated class\n  await page.waitForTimeout(3000);                 // fixed wait — flake source\n  await expect(page.getByRole('heading')).toBeVisible(); // asserts the wrong thing\n});\n~~~","good":"~~~ts\n// Title states the behaviour; assertion maps to the actual outcome.\ntest('a valid discount code reduces the order total', async ({ page }) => {\n  await page.goto('/checkout');\n  await page.getByLabel('Discount code').fill('SAVE10');\n  await page.getByRole('button', { name: 'Apply code' }).click();\n\n  // Web-first assertion waits for the real condition — no fixed wait needed.\n  await expect(page.getByText('Discount applied: -£10.00')).toBeVisible();\n  await expect(page.getByTestId('order-total')).toHaveText('£90.00');\n});\n~~~"},"davidTip":"When you review a test, try to name the exact bug it is supposed to catch, then check the assertion would catch that bug. If you cannot name the bug, or the assertion would survive it, you have found the review comment that matters — everything else is secondary.","miniChallenge":"Draft your team’s one-page test-review standard: locator priority, the no-fixed-waits rule, \"one behaviour per test, assertion required\", and a naming convention. Then mark which items a linter or shared config could enforce automatically, so human review is freed for judgement."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 15 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"A team with one dedicated tester let every automated test become that person’s responsibility. Developers merged freely onto a red pipeline because \"the failures are usually just flaky ones QA is dealing with\", and re-running until green was routine. The habit held right up until a real regression — a broken payment path — failed the suite, got re-run twice, passed once on a timing fluke, and shipped. The post-incident change was not a new tool: it was a rule that a red build blocks all merges, that whoever broke it fixes or reverts, and that flaky tests are quarantined and owned rather than re-run. Within a few weeks red meant \"broken\" again, and the team could once more trust green to mean something.","visualAid":{"type":"comparison","title":"Two cultures around a red build","headers":["Situation","QA-owns-tests culture","Whole-team ownership"],"rows":[["Who owns a test","The tester writes and maintains all tests","Whoever writes the code writes its tests"],["Main build goes red","\"One for QA to look at later\"","Blocks new work; break it, you fix or revert it"],["A test is flaky","Re-run until it passes","Ticket, owner, quarantine, deadline"],["What red comes to mean","Eventually: \"try again\"","Reliably: \"stop and read me\""],["What green then proves","Progressively nothing","That the code actually passed its checks"]]},"davidTip":"The single best health metric for a suite is not coverage percentage — it is what people do in the first thirty seconds after the build goes red. Watch that reflex on your own team honestly; it tells you whether you have a safety net or an expensive decoration."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 15 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A team fell into the habit of a one-line release report — \"suite green, cleared to ship\" — and leadership grew to treat that line as a guarantee. When a defect escaped in an area the suite had never covered, the conversation was ugly: leadership believed \"the tests said it was fine\", and the team had no honest ground to stand on because that was, in effect, what they had said. They changed their reporting to name coverage and residual risk every release — \"confident here, thin there, this area still building\" — and the next escaped bug was a very different conversation, because it landed exactly where the team had already flagged the coverage as thin. Framing results as evidence about risk turned an escape from a broken promise into a predicted, improvable gap.","badGood":{"label":"rubber-stamp report vs evidence-about-risk report","bad":"~~~text\nRelease report:\n  All 1,240 automated tests passing. 100% green. Good to ship. ✅\n~~~","good":"~~~text\nRelease report:\n  Core purchase journey: strong coverage, all green — confident.\n  Partial refunds (new): happy path only; split-refund rounding untested and\n    needs a product decision — this is the residual risk.\n  Recommendation: ship purchase changes; hold partial refunds for a focused\n    pass. Green here is evidence the paths we tested behave — not proof the\n    untested refund paths are safe.\n~~~"},"davidTip":"Before you send any quality report, delete the pass count and the percentage, then see whether the report still says anything. If it collapses without those numbers, you were reporting activity, not risk — rewrite it around what you now know and what you still do not."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 15 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A team measured its testing purely by coverage percentage and grew proud of a large suite — most of it end-to-end UI tests, because that was where features were visible. The suite took nearly an hour to run, failed intermittently on a different test each time, and blocked releases for reasons no one could quickly diagnose. When a new lead reshaped the strategy — pushing logic checks down to fast unit and API tests, keeping only a dozen high-value journeys at the UI layer, and deleting dozens of low-value tests outright — the suite shrank, ran in minutes, stopped flaking, and caught more real bugs than before. The lesson the team took away was that a smaller, faster, trusted suite is worth far more than a large one, and that deleting a test can be as valuable a contribution as writing one.","visualAid":{"type":"comparison","title":"Deciding whether a candidate test earns its place","headers":["Ask about the candidate","If yes","If no"],"rows":[["Does it catch a real, material risk?","It is a candidate worth costing","Decline — it raises a number, not confidence"],["Is it cheapest to catch at this layer?","Write it here","Push it down a layer where it is cheaper"],["Will it cost more to maintain than it saves?","Decline or simplify","Keep it"],["Could a human do this once, faster?","Leave it to a person","Automate it"],["Is this a must-protect area (money, auth, data)?","Ensure real end-to-end coverage","Lighter coverage may be enough"]]},"davidTip":"The most senior thing you can say in a test-planning meeting is often \"let’s not automate that, and here’s why\". Come with the rationale — low risk, already covered cheaper, or maintenance heavier than the bug it would catch — and a clear no protects the suite’s speed and trust far more than another green test ever could.","miniChallenge":"Audit your current suite and find three tests you would delete under the rule \"every test must earn its maintenance cost\". Write the one-line rationale for removing each. If you cannot find three, you may have an unusually disciplined suite — or you may not be looking hard enough."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 15 and l.lesson_number = 5;

